<!--vbase-->
<template>
  <q-card style="width: 1060px; max-width: 1060px" data-test="connection-logs-dialog">
    <q-toolbar class="secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold primary-bg-text">{{
          $t('connection_logs')
        }}</span>
      </q-toolbar-title>

      <q-btn
        flat
        round
        dense
        class="primary-bg-text"
        icon="close"
        data-test="connection-logs-close-btn"
        @click="cleanupOnhide"
        v-close-popup
      />
    </q-toolbar>
    <q-card-section>
      <div class="q-pl-md q-pr-md q-pt-md">
        <DocBitsTable
          :rows="rows"
          :columns="columns"
          row-key="id"
          table-id="connection_logs_table"
          :loading="loading"
          :features="{
            sorting: false,
            filtering: false,
            selection: false,
            bulkActions: false,
            rowActions: false,
            resizable: false,
            pagination: true,
            columnReorder: false,
          }"
          :pagination="paginationState"
          no-data-label="no_data_found"
          flat-style
          table-height="550px"
          @update:pagination="handlePaginationChange"
        >
          <template #body-cell-success="{ row }">
            <q-icon
              :data-test="'connection-log-status-' + (row.success === true ? 'success' : 'failure')"
              :name="row.success === true ? 'check_circle' : 'cancel'"
              :color="row.success === true ? 'green' : 'red'"
              size="20px"
            />
          </template>
          <template #body-cell-message="{ row }">
            <span style="text-wrap: wrap">{{ row.message }}</span>
          </template>
        </DocBitsTable>
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { importApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { date } from 'quasar';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type {
  PaginationChangePayload,
  UnifiedTableColumn,
} from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  mixins: [helperMixin],
  components: { DocBitsTable },
  props: {
    connection_id: {
      type: Number,
      required: true,
    },
    connection_type: {
      type: String,
      required: true,
    },
  },
  mounted: function () {
    this.init();
    this.checkConnectionLogs();
  },
  unmounted: function () {
    this.cleanupOnhide();
  },
  methods: {
    init() {
      this.prepareColumns();
    },

    checkConnectionLogs() {
      try {
        this.resetPagination();
        this.getDataFromServer();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async getDataFromServer() {
      try {
        this.loading = true;
        this.request_params = {} as dynamicObj;
        this.request_params['offset'] = this.page_size * (this.current_page - 1);
        this.request_params['limit'] = this.page_size;
        this.request_params['connection_type'] = this.connection_type;
        this.request_params['connection_id'] = this.connection_id;
        this.request_params['order_by_direction'] = 'desc';
        const response = await importApiService.fetchConnectionLogs(
          this.request_params,
        );
        if (response.success === false) {
          throw { message: response.message };
        }

        this.total_records = response.total_records_count;
        this.prepareRows(response.elements);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    prepareRows(data: any) {
      this.rows = [] as any;
      Array.from(data).forEach((item: any) => {
        const row = item as dynamicObj;
        this.addNewRow(row);
      });
    },

    addNewRow(row: dynamicObj) {
      let newRow: dynamicObj = { ...row };
      newRow['created_on'] = this.formateDate(
        row['created_on'],
        'DD-MM-YYYY HH:mm:ss',
      );
      this.rows.push(newRow);
      return this.rows.length.toString();
    },

    formateDate(strDate: string, dateFormet: string) {
      return date.formatDate(strDate, dateFormet);
    },

    resetPagination() {
      this.current_page = 1;
      this.total_records = 0;
    },

    async handlePaginationChange(payload: PaginationChangePayload) {
      this.current_page = payload.page;
      this.page_size = payload.rowsPerPage;
      try {
        await this.getDataFromServer();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    prepareColumns() {
      this.columns = [
        { name: 'success', label: this.$t('status'), field: 'status', align: 'left' },
        { name: 'created_on', label: this.$t('attempted_on'), field: 'created_on', align: 'left' },
        { name: 'message', label: this.$t('message'), field: 'message', align: 'left' },
      ] as UnifiedTableColumn[];
    },

    cleanupOnhide() {
      this.resetPagination();
    },
  },
  computed: {
    paginationState() {
      return {
        sortBy: null,
        descending: true,
        page: this.current_page,
        rowsPerPage: this.page_size,
        rowsNumber: this.total_records,
      };
    },
  },
  setup() {
    return {
      loading: ref(false),
      request_params: ref({} as dynamicObj),
      current_page: ref(1),
      page_size: ref(10),
      total_records: ref(0),

      columns: ref([] as UnifiedTableColumn[]),
      rows: ref([] as dynamicObj[]),
    };
  },
});
</script>
