<template>
  <div class="import-pipeline">
    <q-tabs
      v-model="activeTab"
      dense
      no-caps
      align="left"
      class="text-primary"
      active-color="primary"
      indicator-color="primary"
    >
      <q-tab
        name="ftp"
        icon="mdi-folder-network"
        :label="tf('import_pipeline_tab_ftp', 'FTP / SFTP')"
      />
      <q-tab
        name="email"
        icon="mdi-email"
        :label="tf('import_pipeline_tab_email', 'Email')"
      />
    </q-tabs>
    <q-separator />

    <q-tab-panels v-model="activeTab" animated>
      <q-tab-panel name="ftp" class="q-pa-sm">
        <div v-if="loading" class="pl-state" data-test="import-pipeline-loading">
          <q-spinner size="1.4rem" />
          {{ tf('import_pipeline_loading', 'Loading pipeline…') }}
        </div>
        <div
          v-else-if="error"
          class="pl-state pl-state--error"
          data-test="import-pipeline-error"
        >
          {{ error }}
        </div>
        <ImportPipelineDiagram v-else :topology="topology" />
      </q-tab-panel>

      <q-tab-panel name="email" class="q-pa-sm">
        <div class="pl-state" data-test="import-pipeline-email-soon">
          {{
            tf(
              'import_pipeline_email_soon',
              'The Email import pipeline view is coming soon.',
            )
          }}
        </div>
      </q-tab-panel>
    </q-tab-panels>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, onMounted, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import ImportApiService from 'src/services/settings/ImportApiService';
import type { FtpImportTopology } from 'src/services/settings/ImportApiService';
import ImportPipelineDiagram from './ImportPipelineDiagram.vue';

export default defineComponent({
  name: 'ImportPipeline',
  components: { ImportPipelineDiagram },
  setup() {
    const { t } = useTranslate();
    const tf = (k: string, f: string) => {
      const v = t.value(k);
      return v !== k ? v : f;
    };

    const activeTab = ref<'ftp' | 'email'>('ftp');
    const loading = ref(true);
    const error = ref('');
    const topology = ref<FtpImportTopology | null>(null);
    const service = new ImportApiService();

    const loadTopology = async () => {
      loading.value = true;
      error.value = '';
      try {
        const res = await service.getFTPImportTopology();
        topology.value = res?.topology ?? null;
      } catch (e) {
        error.value = tf(
          'import_pipeline_load_error',
          'Could not load the import pipeline.',
        );
      } finally {
        loading.value = false;
      }
    };

    onMounted(loadTopology);

    // Re-fetch when the user returns to the FTP tab, so the diagram reflects
    // source changes made elsewhere on the Import page (e.g. add/activate).
    watch(activeTab, (tab) => {
      if (tab === 'ftp') void loadTopology();
    });

    return { tf, activeTab, loading, error, topology };
  },
});
</script>

<style scoped>
.pl-state {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem;
  font-size: 0.85rem;
  color: var(--muted-foreground);
}
.pl-state--error {
  color: var(--destructive, rgb(185 28 28));
}
</style>
