<template>
  <div class="settings-card">
    <!-- Restrict to Pages -->
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('restrict_to_pages') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <q-input
          outlined
          dense
          data-cy="restrict_to_pages"
          tabindex="0"
          type="number"
          class="back-white width-500"
          v-model="user_settings['RESTRICT_TO_PAGES']"
          @update:model-value="
            (val: any) => {
              saveSettings('RESTRICT_TO_PAGES', val);
            }
          "
        >
          <q-tooltip>
            Only process given number of pages every further page will be
            ignored.
          </q-tooltip>
        </q-input>
      </div>
    </div>

    <!-- Payment Terms Days -->
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('payment_terms_days') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <q-input
          outlined
          dense
          data-cy="payment_terms_days"
          tabindex="0"
          type="number"
          class="back-white width-500"
          v-model="user_settings['PAYMENT_TERMS_DAYS']"
          @update:model-value="
            (val: any) => {
              saveSettings('PAYMENT_TERMS_DAYS', val);
            }
          "
        />
      </div>
    </div>

    <!-- Date Pattern -->
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('date_pattern') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <q-select
          outlined
          dense
          class="back-white width-500"
          data-cy="date_pattern"
          v-model="user_settings['DATE_PATTERN']"
          :options="[
            { label: $t('select'), value: '' },
            { label: '%d/%m/%Y', value: '%d/%m/%Y' },
            { label: '%d.%m.%Y', value: '%d.%m.%Y' },
            { label: '%m %d, %Y', value: '%m %d, %Y' },
            { label: '%Y %m, %d', value: '%Y %m, %d' },
          ]"
          emit-value
          map-options
          :label="$t('date_pattern')"
          @update:model-value="
            (val: any) => {
              saveSettings('DATE_PATTERN', val);
            }
          "
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  mixins: [helperMixin],

  methods: {
    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }

      this.showLoading();
      try {
        await this.updateSetting(key, value);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      updateSetting,
    };
  },
  data() {
    return {
      userDialog: ref(false),
      api_key: '',
    };
  },
});
</script>
