<template>
  <div class="pipeline">
    <!-- Empty state when the backend can't provide a topology yet -->
    <div v-if="!topology" class="pipeline-empty" data-test="import-pipeline-empty">
      {{
        tf(
          'import_pipeline_unavailable',
          'Import pipeline topology is not available yet.',
        )
      }}
    </div>

    <template v-else>
      <!-- Region transparency banner: green when imports go to the org region,
           amber when the region can't be confirmed (falls back to default API). -->
      <div
        class="pipeline-banner"
        :class="
          topology.all_match ? 'pipeline-banner--ok' : 'pipeline-banner--warn'
        "
        data-test="import-pipeline-region-banner"
      >
        <Icon
          :icon="topology.all_match ? 'mdi:shield-check' : 'mdi:shield-alert'"
          class="size-4"
        />
        <span v-if="topology.all_match">
          {{
            tf(
              'import_pipeline_region_ok',
              'All FTP/SFTP imports go to your org region',
            )
          }}
          ({{ regionLabel }})
        </span>
        <span v-else>
          {{
            tf(
              'import_pipeline_region_warn',
              'Region could not be confirmed — imports use the default API',
            )
          }}
        </span>
      </div>

      <!-- draw.io-style flow: customer FTP/SFTP sources → DocBits API (region) -->
      <div class="pipeline-canvas" data-test="import-pipeline-flow">
        <svg
          viewBox="0 0 720 150"
          class="pl-svg"
          preserveAspectRatio="xMidYMid meet"
        >
          <defs>
            <marker
              id="il-arrow"
              markerWidth="9"
              markerHeight="9"
              refX="7"
              refY="3"
              orient="auto"
              markerUnits="strokeWidth"
            >
              <path d="M0,0 L7,3 L0,6 Z" class="pl-arrow-head" />
            </marker>
          </defs>

          <path
            class="pl-link"
            d="M236,75 H320"
            fill="none"
            marker-end="url(#il-arrow)"
          />
          <text x="278" y="67" class="pl-link-label">
            {{ tf('import_pipeline_documents', 'documents') }}
          </text>

          <!-- Source: customer FTP/SFTP servers (external, no DocBits region) -->
          <foreignObject x="10" y="40" width="226" height="70">
            <div
              xmlns="http://www.w3.org/1999/xhtml"
              class="pl-box"
              data-test="node-ftp-sources"
            >
              <div class="pl-box-head">
                <Icon icon="mdi:server-network" class="size-4 pl-box-icon" />
                <span class="pl-box-title">
                  {{ tf('import_pipeline_ftp_sources', 'FTP / SFTP sources') }}
                </span>
                <span
                  class="region-pill region-pill--external"
                  :title="tf('import_pipeline_external_hint', 'External customer server')"
                >
                  {{ tf('import_pipeline_external', 'EXTERNAL') }}
                </span>
              </div>
              <div class="pl-box-sub">
                {{ activeCount }}
                {{ tf('import_pipeline_active_sources', 'active source(s)') }}
              </div>
            </div>
          </foreignObject>

          <!-- Target: DocBits API in the resolved region -->
          <foreignObject x="320" y="40" width="386" height="70">
            <div
              xmlns="http://www.w3.org/1999/xhtml"
              class="pl-box pl-box--store"
              data-test="node-docbits-api"
            >
              <div class="pl-box-head">
                <Icon icon="mdi:database-import" class="size-4 pl-box-icon" />
                <span class="pl-box-title">
                  {{ tf('import_pipeline_docbits_api', 'DocBits API') }}
                </span>
                <span
                  class="region-pill"
                  :class="targetPillClass"
                  :title="targetHost"
                >
                  {{ regionLabel }}{{ targetPillIcon }}
                </span>
              </div>
              <div class="pl-box-sub">{{ targetHost }}</div>
            </div>
          </foreignObject>
        </svg>
      </div>

      <!-- What the customer defined, per source -->
      <div
        v-if="sources.length"
        class="pl-sources"
        data-test="import-pipeline-sources"
      >
        <div
          v-for="s in sources"
          :key="s.id"
          class="pl-source"
          :class="{ 'pl-source--inactive': !s.is_active }"
        >
          <div class="pl-source-head">
            <Icon icon="mdi:folder-network-outline" class="size-4" />
            <span class="pl-source-name">
              {{ (s.ftp_type || 'FTP') + ' · ' + (s.server_url || '—') }}
            </span>
            <span
              class="pl-source-badge"
              :class="s.is_active ? 'badge--on' : 'badge--off'"
            >
              {{
                s.is_active
                  ? tf('import_pipeline_active', 'active')
                  : tf('import_pipeline_inactive', 'inactive')
              }}
            </span>
          </div>
          <div class="pl-source-meta">
            <span>
              {{ tf('import_pipeline_import_dir', 'Import') }}:
              <code>{{ s.import_directory || '/' }}</code>
            </span>
            <span v-if="s.move_after_import">
              → {{ tf('import_pipeline_archive', 'Archive') }}:
              <code>{{ s.destination_directory || '—' }}</code>
            </span>
            <span v-if="s.include_subfolder_content">
              · {{ tf('import_pipeline_subfolders', 'incl. subfolders') }}
            </span>
            <span v-if="s.region_override">
              · {{ tf('import_pipeline_region_override', 'region override') }}:
              {{ s.region_override.toUpperCase() }}
            </span>
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, PropType } from 'vue';
import { Icon } from '@iconify/vue';
import { useTranslate } from '@tolgee/vue';
import type { FtpImportTopology } from 'src/services/settings/ImportApiService';

export default defineComponent({
  name: 'ImportPipelineDiagram',
  components: { Icon },
  props: {
    topology: {
      type: Object as PropType<FtpImportTopology | null>,
      default: null,
    },
  },
  setup(props) {
    const { t } = useTranslate();
    const tf = (k: string, f: string) => {
      const v = t.value(k);
      return v !== k ? v : f;
    };

    const regionLabel = computed(() =>
      (
        props.topology?.target_region ??
        props.topology?.org_region ??
        '??'
      ).toUpperCase(),
    );
    const targetHost = computed(() => props.topology?.target_host ?? '');
    // Normalize once so a partial/malformed response can't crash the diagram.
    const sources = computed(() => props.topology?.sources ?? []);
    const activeCount = computed(
      () => sources.value.filter((s) => s.is_active).length,
    );
    const targetPillClass = computed(() =>
      props.topology?.all_match ? 'region-pill--ok' : 'region-pill--advisory',
    );
    const targetPillIcon = computed(() =>
      props.topology?.all_match ? ' ✓' : ' ⓘ',
    );

    return {
      tf,
      regionLabel,
      targetHost,
      sources,
      activeCount,
      targetPillClass,
      targetPillIcon,
    };
  },
});
</script>

