<template>
  <div class="page-container page-height-limit">
    <div class="settings-page-content">
      <!-- Import Pipeline — region transparency for FTP/SFTP & Email imports -->
      <docbits-accordion-panel
        v-model="expandedSections.pipeline"
        icon="mdi:sitemap-outline"
        :title="tf('import_pipeline', 'Import Pipeline')"
        bodyClass="settings-card"
      >
        <ImportPipeline />
      </docbits-accordion-panel>

      <!-- Page Restriction / Email Import -->
      <docbits-accordion-panel
        v-model="expandedSections.pageRestriction"
        icon="mdi:file-document"
        :title="$t('email_import')"
        bodyClass="settings-card"
      >
        <PageRestriction />
      </docbits-accordion-panel>

      <!-- FTP Import -->
      <FtpImportList v-model="expandedSections.ftpImport" />

      <!-- Email Import -->
      <EmailImportList v-model="expandedSections.emailImport" />

      <!-- Inbound Emails -->
      <docbits-accordion-panel
        v-if="user_settings[inbound_emails_setting]"
        v-model="expandedSections.inboundEmails"
        icon="mdi:email-arrow-right"
        :title="$t('inbound_emails')"
        bodyClass="settings-card"
      >
        <InboundEmails />
      </docbits-accordion-panel>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { inbound_emails_setting } from 'src/constants';
import { useDropdownStore, useSettingStore } from 'src/store/main';
import InboundEmails from '../Components/Import/InboundEmails.vue';
import PageRestriction from 'src/pages/Settings/Components/Import/PageRestrictions.vue';
import EmailImportList from 'src/pages/Settings/Components/Import/EmailImportList.vue';
import FtpImportList from 'src/pages/Settings/Components/Import/FtpImportList.vue';
import ImportPipeline from 'src/pages/Settings/Components/Import/ImportPipeline.vue';

export default defineComponent({
  el: '#app',
  components: {
    PageRestriction,
    EmailImportList,
    FtpImportList,
    InboundEmails,
    ImportPipeline,
  },
  data() {
    return {
      expandedSections: {
        pipeline: true,
        pageRestriction: true,
        ftpImport: true,
        emailImport: true,
        inboundEmails: true,
      } as Record<string, boolean>,
    };
  },
  mounted() {
    this.getSubOrgsList();
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { getSubOrgsList } = dropdown_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    const { t } = useTranslate();
    const tf = (k: string, f: string) => {
      const v = t.value(k);
      return v !== k ? v : f;
    };

    return {
      tf,
      getSubOrgsList,
      inbound_emails_setting,
      user_settings,
    };
  },
});
</script>
