              class="full q-ml-sm"
            >
              <template v-slot:append>
                <q-icon
                  v-if="errors['username']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    {{ $t('FIELD_REQUIRED') }}
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
          <div class="col-3" data-test="ftp-import-directory">
            <q-select
              v-model="model['import_directory']"
              :label="$t('import_directory')"
              :options="folderOptions"
              :loading="folderOptionsLoading"
              outlined
              data-cy="ftp_import_directory"
              class="full q-ml-sm"
            />
          </div>
        </div>

        <div class="row q-mt-md">
          <div class="col-2">
            <f-toggle size="xs"
              dense
              class="h-m-5"
              v-if="model['ftp_type'] == 'FTP' || model['ftp_type'] == 'FTPS'"
              data-test="ftp-ignore-certificate-toggle"
              v-model="model['ignore_certificate']"
