            />
            <span
              v-if="model['ftp_type'] == 'FTP' || model['ftp_type'] == 'FTPS'"
            >
              {{ $t('ignore_certificate') }}
            </span>
          </div>
          <div class="col-7" data-test="ftp-password">
            <q-input
              v-model="maskedPassword"
              type="password"
              :label="$t('password')"
              outlined
              data-cy="ftp_password"
              :class="'full q-ml-sm'"
              @focus="handleFocus"
              @blur="handleBlur"
            >
              <template v-slot:append>
                <q-icon
                  class="content-copy-icon"
                  name="content_copy"
                  @click="copyPassword"
                >
                </q-icon>
                <q-icon
                  v-if="errors['password']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    {{ $t('FIELD_REQUIRED') }}
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
          <div class="col-3">
            <div class="mt-15">
              <f-toggle size="xs"
                dense
                class="h-m-5"
                data-test="ftp-archive-after-import-toggle"
                v-model="model['move_after_import']"
                @input="toggleArchiveImport"
              />
              <span>{{ $t('archive_after_import') }}</span>
            </div>
          </div>
        </div>

        <div class="row q-mt-md">
          <div class="col-2" data-test="ftp-doc-type">
            <q-select
              data-cy="ftp_doc_type"
              v-model="selectedDocType"
              outlined
              :options="docTypeOptions"
              option-value="value"
              option-label="label"
              emit-value
              map-options
              clearable
              :label="$t('document_type')"
              @update:model-value="onDocTypeChange"
            />
          </div>
          <div class="col-7" data-test="ftp-file-name-matching-patterns">
            <q-input
              v-model="model['file_name_matching_patterns']"
              :label="$t('file_name_matching_patterns')"
              outlined
              data-cy="ftp_file_name_matching_patterns"
              class="full q-ml-sm"
            />
          </div>
          <div class="col-3" data-test="ftp-archive-directory">
            <q-select
              v-if="model['move_after_import']"
              v-model="model['destination_directory']"
              :label="$t('archive_directory')"
              :options="folderOptions"
              :loading="folderOptionsLoading"
              outlined
              data-cy="ftp_archive_directory"
              class="full q-ml-sm"
            >
              <template v-slot:append>
                <q-icon
                  v-if="
                    validationTriggered &&
                    !model['destination_directory'].trim()
                  "
                  name="error"
                  color="red"
                  class="cursor-pointer"
                >
                  <q-tooltip class="bg-red">
                    {{ $t('CAN_NOT_PROCEED_ON_EMPTY_FIELD') }}
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row q-mt-md">
          <div class="col-2"></div>
          <div class="col-7" data-test="ftp-sub-org">
            <q-select
              data-cy="ftp_sub_org"
              class="full q-ml-sm"
              outlined
              clearable
              v-model="model['sub_org_id']"
              use-input
              :options="filterSubOrgsList"
              @filter="filterSubOrgslistEvent"
              :label="$t('sub_organizations')"
              :loading="sub_org_list_loading"
              emit-value
              map-options
              popup-content-class="dropdown-fit"
            >
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                    <q-tooltip>{{ scope.opt.label }}</q-tooltip>
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
          </div>
          <div class="col-3">
            <div class="mt-15">
              <f-toggle size="xs"
                dense
                class="h-m-5"
                data-test="ftp-include-subfolder-toggle"
                v-model="model['include_subfolder_content']"
                @input="toggleSubfolderContentSetting"
              />
              <span>{{ $t('include_subfolder_content') }}</span>
            </div>
          </div>
        </div>

        <div class="row q-mt-md">
          <div class="col-2"></div>
          <div class="col-7" data-test="ftp-api-key">
            <q-input
              class="full q-ml-sm"
              data-cy="ftp_apiKey"
              outlined
              v-model="api_key_ref"
              readonly
              :class="'bg-disable'"
              :label="$t('token')"
            />
          </div>
          <div class="col-3"></div>
        </div>
      </q-card-section>

      <q-card-section class="p-t-0">
        <div class="row q-mt-md">
          <div class="col-2"></div>
          <div class="col-7">
            <q-btn
              type="submit"
              color="primary"
              class="q-ml-sm float-right"
              id="ftp_btn_save"
              data-test="ftp-save-btn"
              :label="$t('save')"
            />

            <q-btn
              v-if="row_id"
              class="q-ml-sm float-right"
              color="primary"
              :label="$t('test_connection')"
              id="ftp_btn_test_connection"
              data-test="ftp-test-connection-btn"
              @click="checkConnection()"
            >
              <q-tooltip v-if="!row_id">{{
                $t('available_after_save')
              }}</q-tooltip>
            </q-btn>

            <q-btn
              id="ftp_btn_cancel"
              data-test="ftp-cancel-btn"
              class="float-right highlighted-back"
              :label="$t('cancel')"
              v-close-popup
            />
          </div>
          <div class="col-3"></div>
        </div>
      </q-card-section>
    </q-form>

    <q-inner-loading :showing="loading" class="z-index-1">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { storeToRefs } from 'pinia';
import { useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { importApiService } from 'src/services';
import CryptoJS from 'crypto-js';
import { filterApiDocTypes } from 'src/utils/docTypeFilter';
const { AES, mode, enc, pad } = CryptoJS;

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    selected_model: {} as any,
    api_key: { type: String, default: '' },
  },
  components: {},
  data() {
    return {};
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { ftp_types, subOrgList, sub_org_list_loading, active_doc_type_list } =
      storeToRefs(dropdown_store);
    const filterSubOrgsList: any = ref(dropdown_store.subOrgList);
    dropdown_store.prepareDocTypeAndSubTypesList();

    return {
      EMAIL_ENCRYPTION_KEY: ref(''),
      subOrgList,
      sub_org_list_loading,
      filterSubOrgsList,
      ftp_types,
      active_doc_type_list,
      docTypeOptions: ref([] as any),
      selectedDocType: ref(null as any),
      loading: ref(false),
      model: ref({} as any),
      row_id: ref(''),
      errors: ref({} as { [k: string]: any }),
      api_key_ref: ref(''),
      validationTriggered: ref(false),
      folderOptions: ref([] as any),
      folderOptionsLoading: ref(false),
      maskedPassword: ref(''),
      actualPassword: ref(''),
    };
  },
  mounted: function () {
    const EMAIL_ENCRYPTION_KEY = process.env.APP_VUE_EMAIL_ENCRYPTION_KEY;
    if (EMAIL_ENCRYPTION_KEY == undefined) {
      throw 'Missing EMAIL_ENCRYPTION_KEY env - unable to load';
    }
    this.EMAIL_ENCRYPTION_KEY = EMAIL_ENCRYPTION_KEY;
    this.initView();
  },

  methods: {
    initView() {
      this.docTypeOptions = filterApiDocTypes(this.active_doc_type_list);
      this.api_key_ref = this.api_key;

      this.row_id = this.selected_model.hasOwnProperty('id')
        ? this.selected_model.id
        : '';

      this.model = JSON.parse(JSON.stringify(this.selected_model));
      for (let [name, value] of Object.entries(this.model)) {
        if (!value) {
          this.model[name] = '';
        }
      }

      if (this.model['password'] && this.model['password'] !== '') {
        this.actualPassword = this.decryptPassword(
          this.model['password'],
        ).toString(enc.Utf8);
        this.maskedPassword = '*'.repeat(this.actualPassword.length);
      }
      this.model['move_after_import'] = this.model['move_after_import']
        ? true
        : false;
      this.model['ignore_certificate'] = this.model['ignore_certificate']
        ? true
        : false;
      this.model['include_subfolder_content'] = this.model[
        'include_subfolder_content'
      ]
        ? true
        : false;
      this.model['server'] = this.model['server_url'];

      if (this.model['additional_attributes']) {
        try {
          const raw = this.model['additional_attributes'];
          const attrs = typeof raw === 'string' ? JSON.parse(raw) : raw;
          this.selectedDocType = attrs.doc_type || null;
          if (typeof raw !== 'string') {
            this.model['additional_attributes'] = JSON.stringify(raw);
          }
        } catch {
          this.selectedDocType = null;
        }
      }

      this.fetchFolders();
      if (!this.row_id) {
        this.resetForm();
      }
    },

    resetForm() {
      this.selectedDocType = null;
      this.model = {
        username: '',
        password: '',
        server: '',
        port: '22',
        default_directory: '',
        file_name_matching_patterns: '',
        ftp_type: 'SFTP',
        ignore_certificate: false,
        sub_org_id: '',
        move_after_import: false,
        include_subfolder_content: false,
        destination_directory: '',
        import_directory: '',
        additional_attributes: '',
      };
    },

    copyPassword() {
      this.maskedPassword = '*'.repeat(this.actualPassword.length);
      navigator.clipboard.writeText(this.actualPassword).then(() => {
        notify.success(this.$t('password_copy_msg'));
      });
    },

    handleFocus(event: Event) {
      this.maskedPassword = '';
    },
    handleBlur(event: Event) {
      const target = event.target as HTMLInputElement;
      this.maskedPassword = '*'.repeat(target.value.length);
      this.actualPassword = target.value;
      this.model['password'] = target.value;
    },
    async submitFrom() {
      try {
        if (!this.validateForm()) {
          notify.error(this.$t('FIELD_REQUIRED'));
          return;
        }
        this.loading = true;
        const response = await importApiService.ftpImportAddUpdate(
          this.prepareApiData(),
        );

        if (!response.success) {
          throw response;
        }

        if (response.data.hasOwnProperty('id')) {
          this.row_id = response.data.id;
        }
        notify.success(this.$t('MSG_SAVE'));
        await this.checkConnection();
        const event = new CustomEvent('ftp_import_updated', { detail: {} });
        document.dispatchEvent(event);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    validateForm() {
      let validate = true;
      this.validationTriggered = true;
      this.resetErrors();

      // if (!this.model['default_directory']) {
      //   validate = false;
      //   this.errors['default_directory'] = true;
      //   notify.error(this.$t('FIELD_REQUIRED'));
      // }

      const exclude_fields = [
        'default_directory',
        'file_name_matching_patterns',
        'sub_org_id',
        'destination_directory',
        'move_after_import',
        'ignore_certificate',
        'import_directory',
        'include_subfolder_content',
        'additional_attributes',
        'is_deleted',
        'last_mtime',
        'deleted_by',
        'auth_message',
        'auth_failed_count',
        'deleted_on',
        'last_modified_by',
        'last_modified_on',
        'created_by',
        'created_on',
      ];
      for (const [key, value] of Object.entries(this.model)) {
        if (exclude_fields.includes(key)) {
          continue;
        }
        if (key !== 'is_active' && (!value || String(value).length == 0)) {
          validate = false;
          this.errors[key] = true;
        }
      }

      if (!this.validateArchiveDirectory()) {
        validate = false;
      }

      return validate;
    },

    validateArchiveDirectory() {
      if (!this.model.destination_directory) {
        return true;
      }

      const archivePath = this.model.destination_directory.trim();
      const importPath = this.model.import_directory?.trim() || '';
      const defaultPath = this.model.default_directory.trim();

      if (this.model.include_subfolder_content) {
        if (importPath && this.isSubPath(archivePath, importPath)) {
          this.errors['destination_directory'] = true;
          notify.error(this.$t('archive_inside_import_path'));
          return false;
        }
        if (!importPath && this.isSubPath(archivePath, defaultPath)) {
          this.errors['destination_directory'] = true;
          notify.error(this.$t('archive_inside_default_path'));
          return false;
        }
      }
      return true;
    },

    isSubPath(childPath: string, parentPath: string) {
      return childPath.startsWith(parentPath + '/');
    },

    prepareApiData() {
      let encrypted_password = this.encryptPassword();
      this.model.ignore_certificate = this.model.ignore_certificate
        ? true
        : false;
      return {
        password: encrypted_password, // this.model.password,
        username: this.model.username,
        server: this.model.server,
        port: this.model.port,
        ftp_type: this.model.ftp_type,
        file_name_matching_patterns: this.model.file_name_matching_patterns,
        api_key: this.api_key,
        sub_org_id: this.model.sub_org_id,
        id: this.row_id,
        ignore_certificate: this.model.ignore_certificate,
        default_directory: this.model.default_directory,
        move_after_import: this.model.move_after_import,
        destination_directory: this.model.destination_directory,
        include_subfolder_content: this.model.include_subfolder_content,
        import_directory: this.model.import_directory,
        additional_attributes: this.model.additional_attributes || '',
      };
    },

    // todo: Fix password encrption
    encryptPassword() {
      var key = enc.Utf8.parse(this.EMAIL_ENCRYPTION_KEY);
      var encrypted = AES.encrypt(this.actualPassword, key, {
        mode: mode.ECB,
        padding: pad.Pkcs7,
      });
      return encrypted;
    },

    // todo: Fix password decrption
    decryptPassword(password: string) {
      var key = enc.Utf8.parse(this.EMAIL_ENCRYPTION_KEY);
      var decrypted = AES.decrypt(password, key, { mode: mode.ECB });
      return decrypted;
    },

    updateFTPImportEvent() {
      const event = new CustomEvent('email_import_updated', {});
      document.dispatchEvent(event);
    },

    async checkConnection() {
      try {
        if (!this.row_id) {
          return;
        }
        this.loading = true;
        const response = await importApiService.ftpConnectionTest(this.row_id);
        if (
          !response ||
          (response.hasOwnProperty('success') && response.success === false)
        ) {
          throw response;
        }

        notify.success(this.$t('test_connection_success'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    resetErrors() {
      for (const [key, value] of Object.entries(this.model)) {
        this.errors[key] = false;
      }
    },

    filterSubOrgslistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterSubOrgsList = this.subOrgList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterSubOrgsList = this.subOrgList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    onDocTypeChange(value: string | null) {
      if (value) {
        this.model['additional_attributes'] = JSON.stringify({ doc_type: value });
      } else {
        this.model['additional_attributes'] = '';
      }
    },

    toggleArchiveImport() {
      this.model.move_after_import = !this.model.move_after_import;
    },

    toggleIgnoreCertificate() {
      this.model.ignore_certificate = !this.model.ignore_certificate;
    },

    toggleSubfolderContentSetting() {
      this.model.include_subfolder_content =
        !this.model.include_subfolder_content;
    },

    async fetchFolders() {
      if (!this.row_id) return; //No get folders request should be made on config creation
      this.folderOptionsLoading = true;
      try {
        const response = await importApiService.getFTPFolders(this.row_id);
        this.folderOptions = response;
      } catch (err) {
        logError('Error fetching folders:', err);
      } finally {
        this.folderOptionsLoading = false;
      }
    },
  },
});
</script>
<style scoped lang="scss">
.main-card {
  width: 1200px;
  max-width: 1200px;
  height: 600px;
}
</style> 